{
  "proposal": {
    "title": "住得离公司近，谁能支配省下的时间？城市到岗员工的午休与下班时间分配",
    "decision": "优先保留为可检验的研究候选。核心问题是，在通勤缩短幅度相近、岗位和排班稳定的员工中，午间能否自由离岗、下班时能否拒绝临时任务，是否会改变同一工作日里个人活动和工作的时间分配。",
    "event_basis": [
      {
        "event": "E1",
        "observation": "帖主回忆，第一份工作期间从地铁通勤改为步行通勤。后来换工作后，曾住在距公司步行约五分钟处，可以午间回家做饭和午睡。帖主把下班后有更多时间同时归于住得近和很少加班。",
        "locator": "S1 第43至46行",
        "url": "https://www.douban.com/group/topic/317404855/?_spm_id=MTk1MTEwMjcz"
      },
      {
        "event": "E2",
        "observation": "另一位受访者回忆，就近居住期间容易在办公室多待，日常交往也常与附近同事重叠。后来购房搬远时，预算、居住环境和工作生活边界都出现在报道或受访者的解释中。久留期间实际做了什么、谁提出留岗、能否拒绝，均未知。",
        "locator": "S2 第102至114行，久留和交往见第113至114行",
        "url": "https://ftp.laborinfocn.com/articles/76670"
      },
      {
        "event": "背景材料",
        "observation": "商业调查样本中，78%的受访者把通勤时间符合预期列为租房优先考虑因素。这项结果只用于交代调查样本中的住房偏好。",
        "locator": "S3 网页提取版第692至705行",
        "url": "https://reportify-1252068037.cos.ap-beijing.myqcloud.com/media/production/s_c1f2a4c3_c1f2a4c399a9bcd2520d4c6a35e75726.pdf"
      }
    ],
    "conceptualization": "把通勤节省、实际用途和时间支配分开观察。通勤节省以早晚门到门时间的变化衡量，午间额外往返单独记录，并计入全天出行总量。实际用途区分工作、与同事社交、家务照护、休息和个人活动。时间支配指员工能否自行离岗、拒绝或推迟临时任务，以及拒绝后是否有可观察的后果。办公室停留地点和时长不足以判断员工在工作或受到约束。",
    "theoreticalization": {
      "midday": "午休是两段固定工作之间的时间窗口。可自由离岗时，如果往返、进出和必要缓冲之后仍留有足够连续时间，原先做不到的活动才可能进入午休。由此预期，通勤各缩短同样多分钟，跨过活动所需时间门槛的人更可能改变午间用途。午间被要求值守时，预期变化减弱。",
      "end_of_shift": "下班时段的候选机制是，缩短返程后，员工即使多留一会儿也可能在原先预期的时间到家。如果工作团队此时经常提出临时请求，且推迟或拒绝有代价，新增的时间余量可能被工作占用。这个推断要求观察到请求、处置和实际工作，并核对到家时间或下一项既定义务；两起个案尚未核证这一过程。",
      "abstract_relation": "出行阻力下降可以扩大活动的可行范围。活动能否发生，还取决于个人能否离开当前场所、时间能否连续使用，以及谁能对这段时间提出有约束力的要求。于是同一个人的午间自主活动和下班后工作可以同时增加，即使日总工时变化很小。"
    },
    "context_transfer": "在同城到岗工作中，加入住址、岗位和团队稳定、但因交通改善而缩短通勤的比较组。如果午间门到门往返条件保持稳定，午间回家就不应仅因早晚通勤变快而增加。如果晚间同样释放了缓冲时间，且离岗规则和临时任务机会相似，晚间机制应在两类通勤变化中都可观察。只有搬家组变化时，优先检查住房条件、沿途活动和同事网络。这个比较用来检验机制能否迁移。",
    "literature_dialogue": [
      {
        "dimension": "研究对象",
        "finding_and_response": "Wang、Gong 与 Wang 用中国健康与营养调查研究城市劳动者的通勤和劳动供给。其工具变量估计中，较长通勤与较少的每周工作天数和工时相联系，日工时估计未达显著。原研究样本的居住地点保持稳定。本候选接续日内分配问题，检验午间离岗、晚间工作及两者能否在日总量中相抵。",
        "locator": "摘要、§2.2、§3.3至3.5",
        "url": "https://www.mdpi.com/1660-4601/17/13/4631"
      },
      {
        "dimension": "研究议题",
        "finding_and_response": "Elfering 等已把通勤放进工作要求、工作家庭边界和时空自主性的框架，并报告时空自主性调节通勤与工作家庭冲突、离职意向的关联。因而，单提自主性调节通勤后果的增量有限。本候选把检验收窄到同一工作日的两个时点，分别观察实际离岗规则、临时请求和时间用途。",
        "locator": "摘要和讨论，网页约第130至132行",
        "url": "https://onlinelibrary.wiley.com/doi/10.1002/pchj.350"
      },
      {
        "dimension": "边界理论",
        "finding_and_response": "Jachimowicz 等把晨间通勤视为从家庭进入工作角色的过渡，并检验了预先思考工作角色的做法。由此可提出竞争预测：若通勤缩短主要改变心理过渡，首先变化的应是角色转换体验，即使离岗时间、临时任务和活动用途保持稳定。",
        "locator": "摘要，第231行附近",
        "url": "https://pubsonline.informs.org/doi/10.1287/orsc.2020.1370"
      },
      {
        "dimension": "组织制度",
        "finding_and_response": "Kelly 等的团队随机试验同时改变了主管支持和员工对工作时间、地点的控制。该研究为观察组织规则提供依据，联合干预的结果也意味着本候选要分别记录正式排班、主管要求和拒绝后的实际处置。",
        "locator": "摘要、STAR干预说明和讨论",
        "url": "https://journals.sagepub.com/doi/full/10.1177/0003122414531435"
      }
    ],
    "competing_explanations": [
      {
        "explanation": "岗位任务量或排班变化",
        "discriminating_evidence": "比较同一员工、同一岗位和相近日负荷下的记录，并保留通勤未变的同团队员工。若晚间工作随任务高峰同步增加，且通勤未变者出现同样变动，优先采用工作量解释。"
      },
      {
        "explanation": "个人主动延后离岗或同事社交",
        "discriminating_evidence": "逐次记录谁发起、留在办公室做什么、活动能否推迟及拒绝后果。若多出的时间集中在主动工作或可自由退出的社交，组织约束机制缺少支持。"
      },
      {
        "explanation": "住房选择、家庭义务和事后解释",
        "discriminating_evidence": "在搬家前记录预算、住房备选、照护时段和边界偏好，搬家后重复观察。若用途变化与照护调整、住房条件或附近同事网络同步，而通勤变化相近的稳定住址组没有同类表现，应优先考虑选择或同步变化。"
      },
      {
        "explanation": "通勤本身承担心理过渡或沿途活动",
        "discriminating_evidence": "同步记录角色转换体验和沿途购物、社交等活动。若变化集中在主观过渡或原活动转移到其他时段，离岗与任务链条保持稳定，则相应缩小时间支配机制的解释范围。"
      }
    ]
  },
  "evidence_urls": [
    "https://www.mdpi.com/1660-4601/17/13/4631",
    "https://onlinelibrary.wiley.com/doi/10.1002/pchj.350",
    "https://pubsonline.informs.org/doi/10.1287/orsc.2020.1370",
    "https://journals.sagepub.com/doi/full/10.1177/0003122414531435"
  ],
  "academic_increment": {
    "claim": "待验证的学术增量是一项日内分配命题。同等的交通时间节省，在固定午休窗口内可能通过跨过活动所需的连续时间门槛，扩大员工的实际选择；在下班时则可能通过扩大可延后离岗的余量，增加团队临时请求可占用的工作时间。两种变化可在同一员工、同一工作日并存。这个命题把日总量研究无法直接区分的过程，落实到两个有不同组织规则、且可分别被证伪的因果链条。",
    "increment_test": "在相近的通勤节省量下，检验午间活动是否主要集中在有离岗自由且跨过预先确定的活动门槛者，晚间工作增量是否集中在有实际临时请求且难以推迟者。若结果只体现普遍的通勤减负、自主性较高者体验较好，或仅体现两个时段的统计差异，则本候选的实质增量未成立。",
    "status": "已打开的近邻研究支持把问题收窄到上述机制。是否已有研究直接联合检验这两条链路，未知。"
  },
  "feasibility": {
    "current": "现有两件独立事件足以提出研究问题和访谈提纲。公开材料缺少完整时间序列、组织规则和独立行为记录，当前无法检验机制。",
    "minimum_design": "在一个城市先做前瞻性试测。招募预计搬家但维持岗位和班次的到岗员工，并招募同团队同期通勤未变者。以员工工作日为观察单位，拟在变化前后各记录至少两个完整工作周。时间日记覆盖午休起止、门到门出行、实际离岗、全天活动、临时任务的发起与处置、计划和实际到家时点。经同意用排班、去标识任务时间戳或考勤交叉核对，分开记录办公室停留和实际工作。如能取得交通改善组，再开展情境转换检验。",
    "analysis_gate": "试测先检验日记完成度、样本是否覆盖门槛两侧、同等节省量下是否存在离岗规则差异，以及临时请求能否可靠记录。正式分析前固定主要结果、比较组和活动门槛的确定方法。观察性搬家比较用于估计条件关联和核对过程，因果解释取决于能否找到可信的外生变化并排查同期变化。",
    "unknowns": "招募规模、团队规则差异、参与者授权、组织记录可得性、合适的交通变化事件，以及现成调查能否同时测得所需变量，均未知。"
  },
  "limitations": [
    "E1 和 E2 来自不同叙述者及来源，每件事仍主要依赖单方回顾。E1 的五分钟步行阶段与换工作相伴。E2 的搬远与购房、预算和居住偏好相伴。两案都缺少考勤、时间日记或其他当事人的独立印证，组织要求、家庭分工和实际时间增减未知。",
    "商业调查只能说明其样本内的住房偏好。两起事件可以提供行动过程线索，发生率、平均效应和机制方向仍未知。",
    "本轮使用7条原生搜索查询和5次打开，共12个联网动作。其中一个页面返回403，证据数组收录了4个实际打开且用于论证的新页面。本轮沿用初始事件包的定位与证据边界。"
  ]
}
